const skills = $fromAI('skills_score', 80, 'number');
const exp = $fromAI('experience_score', 70, 'number');
const edu = $fromAI('education_score', 100, 'number');

const finalScore = Math.round((skills * 0.50) + (exp * 0.30) + (edu * 0.20));
return { final_match_percentage: finalScore, breakdown: { skills: skills * 0.5, exp: exp * 0.3, edu: edu * 0.2 } };

